INDUSTRY_PAGE = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>行业ETF估值</title><style>body{font-family:system-ui,"Microsoft YaHei";background:#07111f;color:#e9f0fa;margin:0}.wrap{max-width:1400px;margin:auto;padding:24px}nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}nav a{color:#acd1ff;border:1px solid #293d58;border-radius:999px;padding:7px 12px;text-decoration:none}.card{background:#101d30;border:1px solid #293d58;border-radius:14px;padding:18px;margin-bottom:18px}.muted{color:#91a3bb}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.metric{background:#0a1626;border-radius:9px;padding:12px;font-size:22px}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #293d58}th{color:#91a3bb}.good{color:#39d69f}.warn{color:#f2bd4e}@media(max-width:800px){table{font-size:12px}.wrap{padding:12px}}</style></head><body><main class="wrap"><nav><a href="/">做T监控</a><a href="/swing">宽基/策略波段</a><a href="/industry" aria-current="page">行业ETF估值</a><a href="/industry-swing">行业ETF波段建议</a></nav><section class="card"><h1>行业ETF独立估值</h1><p class="muted">行业ETF与原有宽基/策略清单分开管理。PR=PE÷ROE；仅展示研究结果，不自动交易。</p><div id="summary" class="grid"></div></section><section class="card"><h2>行业ETF及关联指数PR</h2><div id="table">加载中...</div></section></main><script>const f=v=>v==null?'—':Number(v).toFixed(2);async function load(){const d=await fetch('/api/industry/valuations').then(r=>r.json()),a=d.items||[];document.querySelector('#summary').innerHTML='<div class="metric">行业ETF '+a.length+' 只</div><div class="metric">已有PR '+a.filter(x=>x.pr!=null).length+' 只</div><div class="metric">仅监控，不自动交易</div>';document.querySelector('#table').innerHTML='<table><thead><tr><th>ETF</th><th>关联指数</th><th>PE</th><th>PB</th><th>ROE</th><th>PR</th><th>数据日期</th><th>状态</th></tr></thead><tbody>'+a.map(x=>'<tr><td>'+x.symbol+' '+x.name+'</td><td>'+x.index_code+' '+x.index_name+'</td><td>'+f(x.pe)+'</td><td>'+f(x.pb)+'</td><td>'+f(x.roe)+'%</td><td><b>'+f(x.pr)+'</b></td><td>'+(x.as_of||'—')+'</td><td class="'+(x.pr!=null?'good':'warn')+'">'+x.status+'</td></tr>').join('')+'</tbody></table>'}load().catch(e=>document.querySelector('#table').textContent='接口暂不可用：'+e.message)</script></body></html>'''

INDUSTRY_SWING_PAGE = r'''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>行业ETF波段建议</title><style>body{font-family:system-ui,"Microsoft YaHei";background:#07111f;color:#e9f0fa;margin:0}.wrap{max-width:1400px;margin:auto;padding:24px}nav{display:flex;gap:10px;flex-wrap:wrap;margin-bottom:20px}nav a{color:#acd1ff;border:1px solid #293d58;border-radius:999px;padding:7px 12px;text-decoration:none}.card{background:#101d30;border:1px solid #293d58;border-radius:14px;padding:18px;margin-bottom:18px}.muted{color:#91a3bb}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:10px;border-bottom:1px solid #293d58}th{color:#91a3bb}.legend{display:flex;gap:18px;flex-wrap:wrap;margin-top:12px;color:#91a3bb;font-size:13px}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;margin-right:6px}.blue{background:#56a8ff}.gray{background:#718096}@media(max-width:800px){table{font-size:12px}.wrap{padding:12px}}</style></head><body><main class="wrap"><nav><a href="/industry">行业ETF估值</a><a href="/industry-swing" aria-current="page">行业ETF波段建议</a><a href="/swing">宽基/策略波段</a></nav><section class="card"><h1>行业ETF波段建议</h1><p class="muted">独立行业ETF池；参考趋势、回调与数据质量，仅作观察，不自动交易。</p><div class="legend"><span><b class="dot blue"></b>趋势评分：60日均线斜率 + 收盘价相对MA60位置，最低为0</span><span><b class="dot gray"></b>评分仅用于趋势强弱参考，不是收益率或单独买卖信号</span></div></section><section class="card"><table><thead><tr><th>ETF</th><th>波段状态</th><th>趋势评分</th><th>执行/数据状态</th></tr></thead><tbody id="rows"><tr><td colspan="4">加载中...</td></tr></tbody></table></section></main><script>const f=v=>v==null?'—':Number(v).toFixed(2);fetch('/api/industry/swing').then(r=>r.json()).then(d=>{document.querySelector('#rows').innerHTML=(d.items||[]).map(x=>'<tr><td>'+x.symbol+' '+(x.name||'')+'</td><td>'+x.state+'</td><td>'+((x.data_status==='DATA_UNAVAILABLE'||x.data_status==='INDUSTRY_HISTORY_PENDING')?'—':f(x.score))+'</td><td>'+x.data_status+'</td></tr>').join('')||'<tr><td colspan="4">暂无行业波段数据</td></tr>'}).catch(e=>document.querySelector('#rows').innerHTML='<tr><td colspan="4">接口暂不可用：'+e.message+'</td></tr>')</script></body></html>'''
